@using sv_8b75c86be6b8484a8aca901c1453b924.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var status = GetStepStatus(step);
        <div class="step-item @status" @onclick="() => OnStepClick(step)">
            <div class="step-circle">
                @if (status == "completed")
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[step]</div>
        </div>
        @if (step < StepNames.Count - 1)
        {
            <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@using sv_8b75c86be6b8484a8aca901c1453b924.Models

<div class="work-entry-form border rounded p-3 mb-3">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Position @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Company Name</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Start Date</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                <label class="form-check-label">Currently working here</label>
            </div>
        </div>
        <div class="col-12">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" value="@Entry.Description"
                      @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;

