toolArgs.file_text:
@using sv_8b75c86be6b8484a8aca901c1453b924.Models

<div class="step-content">
    <h4>Review & Submit</h4>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @if (Personal is not null)
                {
                    <p><strong>Name:</strong> @Personal.FullName</p>
                    <p><strong>Email:</strong> @Personal.Email</p>
                    <p><strong>Phone:</strong> @Personal.Phone</p>
                    <p class="mb-0"><strong>Address:</strong> @Personal.Address</p>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @if (Work is not null)
                {
                    @foreach (var entry in Work.Entries)
                    {
                        <div class="mb-3 pb-3 border-bottom">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                            </p>
                            <p class="mb-0">@entry.Description</p>
                        </div>
                    }
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(2)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @if (References is not null)
                {
                    @foreach (var r in References)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone
                        </div>
                    }
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(3)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string ErrorMessage = string.Empty;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        IsSubmitting = true;
        ErrorMessage = string.Empty;

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

